function buildMatureInsulinChainA21Entry(): BuiltinExperimentalReference {
  const raw3I40 = EXPERIMENTAL_GROUND_TRUTH_PDBS["3I40"].pdbText;
  const chainALines = raw3I40
    .split(/\r?\n/)
    .filter(l => (l.startsWith("ATOM  ") || l.startsWith("TER   ")) && l.charAt(21) === "A");
  const pdb21 = [
    "HEADER    HORMONE (MATURE CHAIN A 21 AA)          01-JUL-09   3I40              ",
    "TITLE     HUMAN INSULIN MATURE A-CHAIN (21 AA, UNIPROT P01308[90-110])          ",
    "SSBOND   1 CYS A    6    CYS A   11                          1555   1555  2.03  ",
    ...chainALines,
    "END"
  ].join("\n");
  return {
    id: "3I40_A_21",
    aliases: ["3I40_A_21", "3I40:A", "3I40_A", "INSULIN_A_21", "INSULIN_A"],
    name: "Insulina ludzka — dojrzały łańcuch A (RCSB PDB: 3I40:A, X-ray 1.85 Å, 21 aa)",
    source: "RCSB_PDB",
    pdbText: pdb21
  };
}

EXPERIMENTAL_GROUND_TRUTH_PDBS["3I40_A_21"] = buildMatureInsulinChainA21Entry();

export function resolveExperimentalReferenceById(queryId: string): BuiltinExperimentalReference | null {
  const q = (queryId || "").trim().toUpperCase();
  if (!q) return null;
  if (q === "UBIQUITIN_76" || q === "P0CG48" || q === "P0CG48_76" || q === "AF-P0CG48-F1") {
    return EXPERIMENTAL_GROUND_TRUTH_PDBS["1UBQ"];
  }
  if (
    q === "INSULIN_A_21" ||
    q === "3I40_A_21" ||
    q === "3I40:A" ||
    q === "3I40_A" ||
    q === "P01308" ||
    q === "AF-P01308-F1"
  ) {
    return EXPERIMENTAL_GROUND_TRUTH_PDBS["3I40_A_21"];
  }
  if (q === "CRAMBIN_46" || q === "P01542") {
    return EXPERIMENTAL_GROUND_TRUTH_PDBS["1CRN"];
  }
  if (q === "CONOTOXIN_25" || q === "P05484" || q === "AF-P05484-F1") {
    return EXPERIMENTAL_GROUND_TRUTH_PDBS["1OMG"];
  }
  if (q === "LYSOZYME_129" || q === "P00698" || q === "AF-P00698-F1") {
    return EXPERIMENTAL_GROUND_TRUTH_PDBS["1LYZ"];
  }
  if (EXPERIMENTAL_GROUND_TRUTH_PDBS[q]) return EXPERIMENTAL_GROUND_TRUTH_PDBS[q];
  for (const ref of Object.values(EXPERIMENTAL_GROUND_TRUTH_PDBS)) {
    if (ref.aliases.includes(q)) return ref;
  }
  return null;
}

